// Block (composition) — a spanning grid of titled feature cards.
// Card owns each surface; Stack arranges card content, while this Block maps item spans to the grid.
import type { CSSProperties, ReactNode, Ref } from "react";
import { Card } from "../components/Card";
import { Media } from "../components/Media";
import { Stack } from "../layouts/Stack";
import "./BentoGrid.css";

export interface BentoGridProps {
  items: {
    id: string;
    title: string;
    description?: string;
    media?: ReactNode;
    colSpan?: number;
    rowSpan?: number;
  }[];
  columns?: number;
  className?: string;
  ref?: Ref<HTMLElement>;
}

type BentoGridStyle = CSSProperties & {
  "--sd-layout-bentogrid-columns": number;
};

type BentoGridItemStyle = CSSProperties & {
  "--sd-layout-bentogrid-column-span": number;
  "--sd-layout-bentogrid-row-span": number;
};

export function BentoGrid({
  items,
  columns = 3,
  className,
  ref,
}: BentoGridProps) {
  return (
    <section
      ref={ref}
      aria-label="Featured capabilities"
      className={className ? `sd-bentogrid ${className}` : "sd-bentogrid"}
      style={{ "--sd-layout-bentogrid-columns": columns } as BentoGridStyle}
    >
      {items.map((item) => (
        <Card
          key={item.id}
          className="sd-bentogrid__item"
          style={
            {
              "--sd-layout-bentogrid-column-span": item.colSpan ?? 1,
              "--sd-layout-bentogrid-row-span": item.rowSpan ?? 1,
            } as BentoGridItemStyle
          }
        >
          <Stack gap="small" className="sd-bentogrid__content">
            {/* The name and its supporting line are ONE unit, so they group at a tighter rung than the
              section's own — otherwise the same gap separates the pair as separates it from
              everything else, and two things read as three (`PageHeader` is the reference). */}
            <>
              <Stack gap="x-small" className="sd-bentogrid__heading">
                <h3 className="sd-bentogrid__title sd-type-title-medium">{item.title}</h3>
                {item.description && (
                  <p className="sd-bentogrid__description sd-type-body-medium">
                    {item.description}
                  </p>
                )}
              </Stack>
            </>
            {item.media && <Media className="sd-bentogrid__media">{item.media}</Media>}
          </Stack>
        </Card>
      ))}
    </section>
  );
}

.sd-bentogrid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--sd-space-large);
  width: 100%;
}

.sd-bentogrid__item {
  grid-column: span 1;
  grid-row: span 1;
}

.sd-bentogrid__title,
.sd-bentogrid__description {
  margin: 0;
}

.sd-bentogrid__description {
  color: var(--sd-color-text-muted);
}

.sd-bentogrid__media {
  min-width: 0;
}

@media (min-width: 768px) {
  .sd-bentogrid {
    grid-template-columns: repeat(var(--sd-layout-bentogrid-columns), minmax(0, 1fr));
  }

  .sd-bentogrid__item {
    grid-column: span var(--sd-layout-bentogrid-column-span);
    grid-row: span var(--sd-layout-bentogrid-row-span);
  }
}
